import{_ as p,a0 as o,w as u,s as l,ao as r,I as a,x as t,a1 as e,A as n}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const D=JSON.parse('{"title":"如何在 Ubuntu Linux 16.04上安裝開源的 Discourse 論壇 | LCTT x X-CMD","titleTemplate":false,"description":"如何在 Ubuntu Linux 16.04上安裝開源的 Discourse 論壇 | LCTT (201607) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在 Ubuntu Linux 16.04上安裝開源的 Discourse 論壇 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 Ubuntu Linux 16.04上安裝開源的 Discourse 論壇 | LCTT (201607) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201607/20160628 How To Setup Open Source Discussion Platform Discourse On Ubuntu Linux 16.04","title":"如何在 Ubuntu Linux 16.04上安裝開源的 Discourse 論壇","tag":"201607","desc":""},"relativePath":"201607/20160628 How To Setup Open Source Discussion Platform Discourse On Ubuntu Linux 16.04.md","filePath":"[post].md"}'),d={name:"201607/20160628 How To Setup Open Source Discussion Platform Discourse On Ubuntu Linux 16.04.md"};function c(h,s,g,b,k,m){const i=o("Link");return u(),l("div",null,[s[13]||(s[13]=r(`<h1 id="如何在-ubuntu-linux-16-04上安裝開源的-discourse-論壇" tabindex="-1">如何在 Ubuntu Linux 16.04上安裝開源的 Discourse 論壇 <a class="header-anchor" href="#如何在-ubuntu-linux-16-04上安裝開源的-discourse-論壇" aria-label="Permalink to “如何在 Ubuntu Linux 16.04上安裝開源的 Discourse 論壇”">​</a></h1><p>Discourse 是一個開源的論壇，它可以以郵件列表、聊天室或者論壇等多種形式工作。它是一個廣受歡迎的現代的論壇工具。在服務端，它使用 Ruby on Rails 和 Postgres 搭建, 並且使用 Redis 緩存來減少讀取時間 , 在客户端，它使用支持 Java Script 的瀏覽器。它非常容易定製，結構良好，並且它提供了轉換插件，可以對你現存的論壇、公告板進行轉換，例如： vBulletin、phpBB、Drupal、SMF 等等。在這篇文章中，我們將學習在 Ubuntu 操作系統下安裝 Discourse。</p><p>它以安全作為設計思想，所以發垃圾信息的人和黑客們不能輕易的實現其企圖。它能很好的支持各種現代設備，並可以相應的調整以手機和平板的顯示。</p><h3 id="在-ubuntu-16-04-上安裝-discourse" tabindex="-1">在 Ubuntu 16.04 上安裝 Discourse <a class="header-anchor" href="#在-ubuntu-16-04-上安裝-discourse" aria-label="Permalink to “在 Ubuntu 16.04 上安裝 Discourse”">​</a></h3><p>讓我們開始吧 ! 最少需要 1G 的內存，並且官方支持的安裝過程需要已經安裝了 docker。 説到 docker，它還需要安裝Git。要滿足以上的兩點要求我們只需要運行下面的命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>wget -qO- https://get.docker.com/ | sh</span></span></code></pre></div><p><img src="http://linuxpitstop.com/wp-content/uploads/2016/06/124.png" alt=""></p><p>用不了多久就安裝好了 docker 和 Git，安裝結束以後，在你的系統上的 /var 分區創建一個 Discourse 文件夾（當然你也可以選擇其他的分區）。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>mkdir /var/discourse</span></span></code></pre></div><p>現在我們來克隆 Discourse 的 Github 倉庫到這個新建的文件夾。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>git clone https://github.com/discourse/discourse_docker.git /var/discourse</span></span></code></pre></div><p>進入這個克隆的文件夾。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>cd /var/discourse</span></span></code></pre></div><p><img src="http://linuxpitstop.com/wp-content/uploads/2016/06/314.png" alt=""></p><p>你將看到“discourse-setup” 腳本文件，運行這個腳本文件進行 Discourse 的初始化。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>./discourse-setup</span></span></code></pre></div><p><strong>備註： 在安裝 discourse 之前請確保你已經安裝好了郵件服務器。</strong></p><p>安裝嚮導將會問你以下六個問題：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Hostname for your Discourse?</span></span>
<span class="line"><span>Email address for admin account? </span></span>
<span class="line"><span>SMTP server address? </span></span>
<span class="line"><span>SMTP user name? </span></span>
<span class="line"><span>SMTP port [587]:</span></span>
<span class="line"><span>SMTP password? []:</span></span></code></pre></div><p><img src="http://linuxpitstop.com/wp-content/uploads/2016/06/411.png" alt=""></p><p>當你提交了以上信息以後, 它會讓你提交確認, 如果一切都很正常，點擊回車以後安裝開始。</p><p><img src="http://linuxpitstop.com/wp-content/uploads/2016/06/511.png" alt=""></p><p>現在“坐等放寬”，需要花費一些時間來完成安裝，倒杯咖啡，看看有什麼錯誤信息沒有。</p><p><img src="http://linuxpitstop.com/wp-content/uploads/2016/06/610.png" alt=""></p><p>安裝成功以後看起來應該像這樣。</p><p><img src="http://linuxpitstop.com/wp-content/uploads/2016/06/710.png" alt=""></p><p>現在打開瀏覽器，如果已經做了域名解析，你可以使用你的域名來連接 Discourse 頁面 ，否則你只能使用IP地址了。你將看到如下信息：</p><p><img src="http://linuxpitstop.com/wp-content/uploads/2016/06/85.png" alt=""></p><p>就是這個，點擊 “Sign Up” 選項創建一個新的賬户，然後進行你的 Discourse 設置。</p><p><img src="http://linuxpitstop.com/wp-content/uploads/2016/06/106.png" alt=""></p><h3 id="結論" tabindex="-1">結論 <a class="header-anchor" href="#結論" aria-label="Permalink to “結論”">​</a></h3><p>它安裝簡便，運行完美。 它擁有現代論壇所有必備功能。它以 GPL 發佈，是完全開源的產品。簡單、易用、以及特性豐富是它的最大特點。希望你喜歡這篇文章，如果有問題，你可以給我們留言。</p><hr>`,33)),a("p",null,[s[1]||(s[1]=t("via: ",-1)),e(i,{href:"http://linuxpitstop.com/install-discourse-on-ubuntu-linux-16-04/"},{default:n(()=>[...s[0]||(s[0]=[t("http://linuxpitstop.com/install-discourse-on-ubuntu-linux-16-04/",-1)])]),_:1})]),a("p",null,[s[5]||(s[5]=t("作者：",-1)),e(i,{href:"http://linuxpitstop.com/author/aun/"},{default:n(()=>[...s[2]||(s[2]=[t("Aun",-1)])]),_:1}),s[6]||(s[6]=t(" 譯者：",-1)),e(i,{href:"https://github.com/kokialoves"},{default:n(()=>[...s[3]||(s[3]=[t("kokialoves",-1)])]),_:1}),s[7]||(s[7]=t(" 校對：",-1)),e(i,{href:"https://github.com/wxy"},{default:n(()=>[...s[4]||(s[4]=[t("wxy",-1)])]),_:1})]),a("p",null,[s[10]||(s[10]=t("本文由 ",-1)),e(i,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...s[8]||(s[8]=[t("LCTT",-1)])]),_:1}),s[11]||(s[11]=t(" 原創編譯，",-1)),e(i,{href:"https://linux.cn/"},{default:n(()=>[...s[9]||(s[9]=[t("Linux中國",-1)])]),_:1}),s[12]||(s[12]=t(" 榮譽推出",-1))])])}const T=p(d,[["render",c]]);export